function pp_names(mixed $v): array {$r=is_string($v)?pp_parse($v,explode("\n",$v)):$v;return array_slice(array_values(array_filter(array_map(fn($x)=>pp_clean($x,200),is_array($r)?$r:[]))),0,20);}
