   if($section==='roles'&&(!$target||!$target['email_verified']||$target['status']!=='active'))throw new PPError(400,'Primero debe entrar con una cuenta verificada.');
   if($section==='invite'){$name=pp_clean($p['display_name']??'',120);if(mb_strlen($name)<2)throw new PPError(400,'Introduce el nombre visible.');if($target&&$target['email_verified'])throw new PPError(409,'La cuenta ya está verificada. Asígnale el rol desde Usuarios.');if(!$target)pp_insert('reader_profiles',['email'=>$email,'display_name'=>$name,'email_verified'=>0]);else pp_update('reader_profiles',['display_name'=>$name,'status'=>'active'],'email',$email);}
